want = {"booking":5,"symptoms":55,"disease":65,"reschedule":25,"timings":20,"info":20,"followup":15,"emergency":15,"difficult":20,"closing":10}
seen, out = set(), []
for k, convs in D.items():
    assert len(convs) == want[k], (k, len(convs))
    for c in convs:
        assert c[0] not in seen and len(c) % 2 == 0; seen.add(c[0])
        msgs = [{"role":"system","content":S}] + [{"role":"user" if i%2==0 else "assistant","content":t} for i,t in enumerate(c)]
        out.append(json.dumps({"messages":msgs}, ensure_ascii=False))
assert len(out) == 250
open("kodeara_051_300.jsonl","w",encoding="utf-8").write("\n".join(out)+"\n")
print("Wrote", len(out), "records")